// Explicit experimental-schema migration on a stopped owned copy only.
#include <rocksdb/db.h>
#include <rocksdb/table.h>
#include <rocksdb/write_batch.h>
#include <openssl/evp.h>
#include "json.hpp"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <memory>
#include <cstdarg>
#include <csignal>
#include <cstdlib>
using Json=nlohmann::json;namespace fs=std::filesystem;
class SilentLogger final:public rocksdb::Logger{public:void Logv(const char*,va_list)override{}};
void ok(const rocksdb::Status& s){if(!s.ok())throw std::runtime_error(s.ToString());}
std::string hash(std::string_view s){unsigned char out[32];unsigned n=0;if(EVP_Digest(s.data(),s.size(),out,&n,EVP_sha256(),nullptr)!=1||n!=32)throw std::runtime_error("Digest failed");static constexpr char hex[]="0123456789abcdef";std::string text="0x";for(auto b:out){text+=hex[b>>4];text+=hex[b&15];}return text;}
std::string get(rocksdb::DB& db,const std::string& key){std::string s;ok(db.Get(rocksdb::ReadOptions(),key,&s));return s;}
uint64_t quantity(const std::string& s){if(s.size()<3||s.size()>18||s.substr(0,2)!="0x"||(s.size()>3&&s[2]=='0'))throw std::runtime_error("Noncanonical quantity");uint64_t n=0;for(auto c:s.substr(2)){unsigned d;if(c>='0'&&c<='9')d=c-'0';else if(c>='a'&&c<='f')d=c-'a'+10;else throw std::runtime_error("Invalid quantity");n=(n<<4)|d;}return n;}
Json inspect(rocksdb::DB& db,const Json& request){const auto schema=get(db,"meta/schema");if(schema!="nano/1"&&schema!="nano/2-state-pruned")throw std::runtime_error("Unsupported migration schema");const auto token=Json::parse(get(db,"fork-checkpoint/v1/token"));if(token!=request.at("expectedCheckpoint"))throw std::runtime_error("Migration checkpoint differs from external commitment");if(!quantity(token.at("sequence"))||!token.at("digest").is_string())throw std::runtime_error("Invalid migration checkpoint");const auto payload=get(db,"fork-checkpoint/v1/payload");if(payload.empty()||payload.size()>quantity(request.at("limits").at("stateBytes")))throw std::runtime_error("Migration checkpoint exceeds audit budget");if(hash(payload)!=token.at("digest").get_ref<const std::string&>())throw std::runtime_error("Migration checkpoint payload digest mismatch");const auto retention=Json::parse(get(db,"execution-state-pruning/v1"));if(!retention.is_object()||retention.size()!=3||quantity(retention.at("before"))<=1||quantity(retention.at("before"))>quantity(retention.at("anchorNumber")))throw std::runtime_error("Invalid legacy retention marker");const auto anchor=retention.at("anchorHash").get<std::string>();if(anchor.size()!=66||anchor.substr(0,2)!="0x"||anchor.find_first_not_of("0123456789abcdef",2)!=std::string::npos)throw std::runtime_error("Invalid retention anchor hash");const auto linked=Json::parse(get(db,"execution-checkpoint/v1"));if(linked.at("digest")!=token.at("digest"))throw std::runtime_error("Migration execution binding mismatch");return {{"schema",schema},{"checkpoint",token},{"retention",retention},{"execution",linked}};}
std::string except_schema(rocksdb::DB& db){std::unique_ptr<EVP_MD_CTX,decltype(&EVP_MD_CTX_free)> ctx(EVP_MD_CTX_new(),EVP_MD_CTX_free);if(!ctx||EVP_DigestInit_ex(ctx.get(),EVP_sha256(),nullptr)!=1)throw std::runtime_error("Digest init failed");auto frame=[&](rocksdb::Slice s){unsigned char size[8];uint64_t n=s.size();for(unsigned i=0;i<8;++i)size[7-i]=static_cast<unsigned char>(n>>(i*8));if(EVP_DigestUpdate(ctx.get(),size,8)!=1||EVP_DigestUpdate(ctx.get(),s.data(),s.size())!=1)throw std::runtime_error("Digest update failed");};rocksdb::ReadOptions ro;ro.verify_checksums=true;ro.fill_cache=false;std::unique_ptr<rocksdb::Iterator> it(db.NewIterator(ro));for(it->SeekToFirst();it->Valid();it->Next()){if(it->key().ToString()=="meta/schema")continue;frame(it->key());frame(it->value());}ok(it->status());unsigned char out[32];unsigned n=0;if(EVP_DigestFinal_ex(ctx.get(),out,&n)!=1||n!=32)throw std::runtime_error("Digest final failed");static constexpr char h[]="0123456789abcdef";std::string text;for(auto b:out){text+=h[b>>4];text+=h[b&15];}return text;}
void stage(const char* name){const auto* stop=std::getenv("NANO_TEST_MIGRATION_STOP");if(stop&&std::string(stop)==name){std::cerr<<"migration-test-stage:"<<name<<std::endl;std::raise(SIGSTOP);}}
int main(int argc,char** argv){try{
 if(argc!=5||std::string(argv[1])!="--offline-owned-copy"||std::string(argv[3])!="--audit-request")throw std::invalid_argument("Usage: migrate-pruned-owned-copy --offline-owned-copy COPY/chain --audit-request VERIFIED-REQUEST.json");
 fs::path p(argv[2]);for(auto q=p;!q.empty();q=q.parent_path()){if(fs::is_symlink(q))throw std::runtime_error("Symlink path refused");if(q==q.parent_path())break;}p=fs::canonical(p);const auto marker=p.parent_path()/".nano-owned-schema-migration-copy";if(p.filename()!="chain"||!fs::is_regular_file(p/"CURRENT")||fs::is_symlink(marker))throw std::runtime_error("Owned migration chain copy required");for(const auto& e:fs::recursive_directory_iterator(p))if(e.is_symlink())throw std::runtime_error("Database symlinks refused");std::ifstream flag(marker);std::string line;std::getline(flag,line);if(line!="owned-offline-schema-migration-v1")throw std::runtime_error("Explicit owned migration marker required");if(fs::is_symlink(argv[4])||!fs::is_regular_file(argv[4])||fs::file_size(argv[4])>1024*1024)throw std::runtime_error("Bounded audit request required");std::ifstream file(argv[4]);Json request;file>>request;
 rocksdb::Options options;options.create_if_missing=false;options.paranoid_checks=true;options.allow_fallocate=false;options.info_log=std::make_shared<SilentLogger>();rocksdb::BlockBasedTableOptions tables;tables.format_version=6;options.table_factory.reset(rocksdb::NewBlockBasedTableFactory(tables));rocksdb::DB* raw=nullptr;ok(rocksdb::DB::OpenForReadOnly(options,p.string(),&raw));std::unique_ptr<rocksdb::DB> db(raw);const auto initial=inspect(*db,request);const auto digest=except_schema(*db);if(initial.at("schema")=="nano/2-state-pruned"){std::cout<<Json{{"alreadyMigrated",true},{"checkpoint",initial.at("checkpoint")},{"nonSchemaContentSha256",digest},{"writes",0},{"ownedCopyOnly",true}}.dump()<<'\n';return 0;}db.reset();
 ok(rocksdb::DB::Open(options,p.string(),&raw));db.reset(raw);if(inspect(*db,request)!=initial||except_schema(*db)!=digest)throw std::runtime_error("Owned copy changed between verification and exclusive open");stage("before-write");rocksdb::WriteBatch batch;batch.Put("meta/schema","nano/2-state-pruned");rocksdb::WriteOptions write;write.sync=true;ok(db->Write(write,&batch));stage("after-write");const auto final=inspect(*db,request);if(final.at("schema")!="nano/2-state-pruned"||except_schema(*db)!=digest)throw std::runtime_error("Schema migration changed other content");std::cout<<Json{{"alreadyMigrated",false},{"from","nano/1"},{"to","nano/2-state-pruned"},{"checkpoint",final.at("checkpoint")},{"nonSchemaContentSha256",digest},{"onlySchemaChanged",true},{"syncWrite",true},{"ownedCopyOnly",true},{"productionMigrationQualified",false}}.dump()<<'\n';return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
